sp_widget.client_script:
function($scope) {

    var c = this;

    c.form = {
        caller: {
            value: ''
        },
        from: {
            value: ''
        },
        destination: {
            value: ''
        },
        startdate: '',
        return_trip: false,
        returndate: '',
        short_description: '',
        travel_type: ''
    };

    c.errors = {};
    c.submitting = false;
    c.success = false;
    c.serverError = '';


    // Return checkbox
    c.returnChanged = function() {

        if (!c.form.return_trip) {
            c.form.returndate = '';
            c.errors.returndate = '';
        }
    };


    // Validation
    c.validate = function() {

        c.errors = {};

        var valid = true;

        if (!c.form.caller.value) {
            c.errors.caller = 'Caller is required.';
            valid = false;
        }

        if (!c.form.from.value) {
            c.errors.from = 'From location is required.';
            valid = false;
        }

        if (!c.form.destination.value) {
            c.errors.destination = 'Destination is required.';
            valid = false;
        }

        if (
            c.form.from.value &&
            c.form.destination.value &&
            c.form.from.value === c.form.destination.value
        ) {
            c.errors.destination =
                'Destination cannot be same as From location.';
            valid = false;
        }

        if (!c.form.startdate) {
            c.errors.startdate = 'Start date is required.';
            valid = false;
        }

        if (c.form.return_trip) {

            if (!c.form.returndate) {

                c.errors.returndate =
                    'Return date is required for a return trip.';

                valid = false;

            } else if (
                c.form.startdate &&
                c.form.returndate < c.form.startdate
            ) {

                c.errors.returndate =
                    'Return date cannot be before start date.';

                valid = false;
            }
        }

        if (!c.form.travel_type) {
            c.errors.travel_type =
                'Please select travel type.';
            valid = false;
        }

        if (!c.form.short_description ||
            !c.form.short_description.trim()) {

            c.errors.short_description =
                'Short description is required.';

            valid = false;
        }

        return valid;
    };


    // Submit
    c.submitForm = function() {

        c.success = false;
        c.serverError = '';

        if (!c.validate()) {
            return;
        }

        c.submitting = true;

        c.server.get({
            action: 'createBooking',

            caller: c.form.caller.value,

            from: c.form.from.value,

            destination: c.form.destination.value,

            startdate: c.form.startdate,

            return_trip: c.form.return_trip,

            returndate: c.form.returndate,

            short_description:
                c.form.short_description.trim(),

            travel_type: c.form.travel_type
        }).then(function(response) {

            c.submitting = false;

            if (response.data.success) {

                c.success = true;
                c.bookingNumber =
                    response.data.number;

                // Clear form
                c.form = {
                    caller: {
                        value: ''
                    },
                    from: {
                        value: ''
                    },
                    destination: {
                        value: ''
                    },
                    startdate: '',
                    return_trip: false,
                    returndate: '',
                    short_description: '',
                    travel_type: ''
                };

            } else {

                c.serverError =
                    response.data.error ||
                    'Unable to create travel booking.';

            }

        }, function() {

            c.submitting = false;

            c.serverError =
                'Server error occurred while creating the booking.';

        });
    };

}

sp_widget.script:
(function() {

    data.success = false;

    if (input && input.action === 'createBooking') {

        var requiredFields = [
            'caller',
            'from',
            'destination',
            'startdate',
            'travel_type',
            'short_description'
        ];

        // Required field validation
        for (var i = 0; i < requiredFields.length; i++) {

            var field = requiredFields[i];

            if (!input[field] ||
                String(input[field]).trim() === '') {

                data.error =
                    field + ' is required.';

                return;
            }
        }


        // Validate travel type
        if (
            input.travel_type !== 'domestic' &&
            input.travel_type !== 'international'
        ) {

            data.error =
                'Invalid travel type.';

            return;
        }


        // Return trip validation
        var isReturn =
            input.return_trip === true ||
            input.return_trip === 'true';

        if (isReturn && !input.returndate) {

            data.error =
                'Return date is required for a return trip.';

            return;
        }


        // Return date validation
        if (
            isReturn &&
            input.startdate &&
            input.returndate < input.startdate
        ) {

            data.error =
                'Return date cannot be before start date.';

            return;
        }


        // Validate caller
        var callerGR = new GlideRecord('sys_user');

        if (!callerGR.get(input.caller)) {

            data.error =
                'Invalid caller selected.';

            return;
        }


        // Create Travel Booking
        var booking =
            new GlideRecord(
                'x_2166443_info_t_0_travelbooking'
            );

        booking.initialize();


        // Reference fields
        booking.setValue(
            'caller',
            input.caller
        );

        booking.setValue(
            'from',
            input.from
        );

        booking.setValue(
            'destination',
            input.destination
        );


        // Dates
        booking.setValue(
            'startdate',
            input.startdate
        );


        // Return checkbox
        booking.setValue(
            'return',
            isReturn
        );


        // Return date
        if (isReturn) {

            booking.setValue(
                'returndate',
                input.returndate
            );

        } else {

            booking.setValue(
                'returndate',
                ''
            );
        }


        // Other fields
        booking.setValue(
            'short_description',
            input.short_description
        );

        booking.setValue(
            'travel_type',
            input.travel_type
        );


        // Insert
        var sysId = booking.insert();


        if (!sysId) {

            data.error =
                'Travel booking could not be created.';

            return;
        }


        // Success
        data.success = true;

        data.sys_id = sysId;

        data.number =
            booking.getValue('number');
    }

})();
